/**
 * Proves that the committed Apple project is exactly what `apps/apple/project.yml`
 * generates, without touching the working tree.
 *
 * `apps/apple/VOID.xcodeproj/project.pbxproj` is a build artifact: XcodeGen writes
 * it from the yml. Regenerating in place and trusting the exit code proves nothing,
 * because XcodeGen succeeds whether or not the result matches what is committed.
 * So the check copies the source tree to a scratch directory, generates there, and
 * compares the generated bytes with the ones in the repository. A stale project, a
 * hand-edited pbxproj, a yml change that was never regenerated and a generation
 * that is not reproducible all fail the same way, with the differing file named.
 *
 * The copy deliberately excludes the existing project and the generated Info.plist,
 * so the generated tree is the only candidate for the comparison and a file that
 * stopped being generated cannot pass by accident.
 *
 * macOS only, and it needs XcodeGen (`brew install xcodegen`) plus a checkout.
 */

import { spawnSync } from "node:child_process";
import { cpSync, mkdtempSync, readdirSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, relative, resolve, sep } from "node:path";

const root = resolve(import.meta.dirname, "..", "..");
const apple = join(root, "apps", "apple");
const projectDirectory = "VOID.xcodeproj";
const generatedPlist = "VOIDApp/Info.plist";
/**
 * SwiftPM writes package resolution state under `project.xcworkspace/xcshareddata`.
 * XcodeGen never writes it, so comparing it would report a difference on a clean
 * tree the moment a package is resolved. Everything else under the project is
 * generated and is compared.
 */
const writtenElsewhere = `${projectDirectory}/project.xcworkspace/xcshareddata/`;
const excluded = new Set([projectDirectory, generatedPlist]);

const generated = spawnSync("xcodegen", ["--version"], { encoding: "utf8" });
if (generated.error) {
  console.error("xcodegen is not on PATH; install it with `brew install xcodegen`.");
  process.exit(1);
}
console.log(`xcodegen ${generated.stdout.trim()}`);

const scratch = mkdtempSync(join(tmpdir(), "void-apple-project-"));
try {
  const copy = join(scratch, "apple");
  cpSync(apple, copy, {
    recursive: true,
    filter: (source) => {
      const path = relative(apple, source);
      if (path === "") return true;
      const name = path.split(sep)[0];
      return !excluded.has(path) && !excluded.has(name) && name !== ".build" && name !== "DerivedData";
    },
  });

  const run = spawnSync("xcodegen", ["generate", "--spec", "project.yml"], { cwd: copy, encoding: "utf8" });
  if (run.error || run.status !== 0) {
    console.error(run.error?.message ?? run.stderr);
    process.exit(1);
  }

  /** Relative path -> bytes, for the generated files of one tree. */
  function files(directory, prefix) {
    const found = new Map();
    const walk = (current) => {
      for (const entry of readdirSync(current, { withFileTypes: true })) {
        const path = join(current, entry.name);
        if (entry.isDirectory()) {
          walk(path);
        } else {
          found.set(`${prefix}${relative(directory, path).split(sep).join("/")}`, readFileSync(path));
        }
      }
    };
    walk(directory);
    return found;
  }

  const generatedProject = files(join(copy, projectDirectory), `${projectDirectory}/`);
  const generatedPlistBytes = readFileSync(join(copy, generatedPlist));
  const committedProject = files(join(apple, projectDirectory), `${projectDirectory}/`);
  const committedPlistBytes = readFileSync(join(apple, generatedPlist));

  const differences = [];
  for (const [path, bytes] of generatedProject) {
    if (path.startsWith(writtenElsewhere)) continue;
    const committed = committedProject.get(path);
    if (committed === undefined) differences.push(`${path} is generated but not committed`);
    else if (!committed.equals(bytes)) differences.push(`${path} differs from project.yml`);
  }
  for (const path of committedProject.keys()) {
    if (path.startsWith(writtenElsewhere) || generatedProject.has(path)) continue;
    differences.push(`${path} is committed but no longer generated`);
  }
  if (!committedPlistBytes.equals(generatedPlistBytes)) differences.push(`${generatedPlist} differs from project.yml`);

  if (differences.length > 0) {
    console.error("The committed Apple project is not what project.yml generates:");
    for (const difference of differences) console.error(`  ${difference}`);
    console.error("Run `pnpm apple:project` and commit the result.");
    process.exit(1);
  }
  console.log(
    `apps/apple/${projectDirectory} and ${generatedPlist} match project.yml (${generatedProject.size} generated files).`,
  );
} finally {
  rmSync(scratch, { recursive: true, force: true });
}
